import time
import six
import sys

__PROPAGATE_LAST_EXCEPTION = '__PROPAGATE_LAST_EXCEPTION'
__PROPAGATE_RETURNED_VALUE = '__PROPAGATE_RETURNED_VALUE'


def _is_time_exceeded(time_limit):
    return time.time() > time_limit


def _is_raisable(object):
    if object is None:
        return False
    elif isinstance(object, Exception):
        return True
    elif type(object) is type and issubclass(object, Exception):
        return True
    else:
        return False


def _return_or_raise_on_success(returned_value, on_success):
    if on_success == __PROPAGATE_RETURNED_VALUE:
        return returned_value
    elif _is_raisable(on_success):
        raise on_success
    else:
        return on_success


def _return_or_raise_on_fail(exception_info, on_fail):
    if on_fail == __PROPAGATE_LAST_EXCEPTION:
        six.reraise(exception_info[0], exception_info[1], exception_info[2])
    elif _is_raisable(on_fail):
        raise on_fail
    else:
        return on_fail


def _keep_running_until_no_exception_or_timeout(timeout, delay, on_success, on_timeout, method, args, kwargs):
        time_limit = time.time() + timeout
        while True:
            try:
                returned_value = method(*args, **kwargs)
            except:
                if _is_time_exceeded(time_limit):
                    return _return_or_raise_on_fail(sys.exc_info(), on_timeout)
                else:
                    time.sleep(delay)
            else:
                return _return_or_raise_on_success(returned_value, on_success)


def retry_until_no_exception_or_timeout(timeout, delay=1, on_timeout=__PROPAGATE_LAST_EXCEPTION, on_success=__PROPAGATE_RETURNED_VALUE):
    """
    A decorator that invokes the decorated method until it successfully returns without raising an exception
    or given amount of time passes. There is a delay between method calls to prevent methods that
    raise an exception immediately from using 100% CPU. All times are in seconds.

    By default, the decorator will return whatever the decorated method returns or raise whatever exception it raised last.
    This behavior may be changed using on_timeout and on_success parameters. If their value is an Exception or an Exception class,
    it is raised. If it is any other value, that value is returned.
    """
    def _wrap(method):
        def _wrapped_method(*args, **kwargs):
            return _keep_running_until_no_exception_or_timeout(timeout=timeout,
                                                               delay=delay,
                                                               on_success=on_success,
                                                               on_timeout=on_timeout,
                                                               method=method,
                                                               args=args,
                                                               kwargs=kwargs)
        return _wrapped_method
    return _wrap


def _keep_running_until_no_exception_or_out_of_attempts(attempts, delay, on_success, on_fail, method, args, kwargs):
        for attempt in range(attempts):
            try:
                returned_value = method(*args, **kwargs)
            except:
                if attempt == attempts - 1:
                    return _return_or_raise_on_fail(sys.exc_info(), on_fail)
                else:
                    time.sleep(delay)
            else:
                return _return_or_raise_on_success(returned_value, on_success)


def retry_until_no_exception_or_out_of_attempts(attempts, delay=1, on_fail=__PROPAGATE_LAST_EXCEPTION, on_success=__PROPAGATE_RETURNED_VALUE):
    """
    A decorator that invokes the decorated method until it successfully returns without raising an exception
    or given amount of attempts is used. There is a delay between method calls to prevent methods that
    raise an exception immediately from using 100% CPU. All times are in seconds.

    By default, the decorator will return whatever the decorated method returns or raise whatever exception it raised last.
    This behavior may be changed using on_timeout and on_success parameters. If their value is an Exception or an Exception class,
    it is raised. If it is any other value, that value is returned.
    """

    def _wrap(method):
        def _wrapped_method(*args, **kwargs):
            return _keep_running_until_no_exception_or_out_of_attempts(attempts=attempts,
                                                                       delay=delay,
                                                                       on_success=on_success,
                                                                       on_fail=on_fail,
                                                                       method=method,
                                                                       args=args,
                                                                       kwargs=kwargs)
        return _wrapped_method
    return _wrap
